import{_ as o,o as t,c as d,a3 as c}from"./chunks/framework.D8G7yXPy.js";const f=JSON.parse('{"title":"应用配置","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md"}'),a={name:"reference/configuration.md"};function r(i,e,n,s,_,p){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="应用配置" tabindex="-1">应用配置 <a class="header-anchor" href="#应用配置" aria-label="Permalink to &quot;应用配置&quot;">​</a></h1><p>应用配置与站外文档配置分属两个仓库。这里说明 Ray Template 应用中的 <code>@/app-config</code>、Vite 配置和运行期设置。运行期保存的用户偏好可能覆盖源码默认值，验证默认设置时使用干净的浏览器存储。</p><table tabindex="0"><thead><tr><th>文件</th><th>配置</th></tr></thead><tbody><tr><td><code>apps/admin/src/app-config/app-config.ts</code></td><td><code>GLOBAL_CLASS_NAMES</code>（明暗类与 CSS 变量）、<code>MESSAGE_PROVIDER</code>（上下文消息，默认最多 5 条、不可关闭）、<code>LAYOUT_CONTENT_SPIN_WHEN_ROUTE_CHANGE</code>（默认关）、<code>APP_GLOBAL_LOADING</code>、<code>PRE_LOADING_CONFIG</code>、<code>APP_CATCH_KEY</code> / <code>APP_CATCH_KEY_PREFIX</code>、<code>CONTENT_TRANSITION_OPTIONS</code>。</td></tr><tr><td><code>apps/admin/src/app-config/design-config.ts</code></td><td><code>APP_THEME</code> 的候选色、构建品牌蓝 <code>#3b63d9</code>、现代化预设的明暗覆盖、ECharts 默认主题。四套预设在 <code>packages/ui/src/theme-presets.ts</code>。</td></tr><tr><td><code>apps/admin/src/app-config/local-config.ts</code></td><td><code>LOCAL_OPTIONS</code>、<code>SYSTEM_DEFAULT_LOCAL</code>、<code>SYSTEM_FALLBACK_LOCALE</code>、<code>DAYJS_LOCAL_MAP</code>、<code>DEFAULT_DAYJS_LOCAL</code>。默认与回退语言为 <code>zh-CN</code>。</td></tr><tr><td><code>apps/admin/src/app-config/request-config.ts</code></td><td><code>AXIOS_CONFIG</code>。默认同源相对地址、5 秒超时、<code>withCredentials: false</code>、JSON Content-Type。</td></tr><tr><td><code>apps/admin/src/app-config/router-config.ts</code></td><td><code>SETUP_ROUTER_ACTION</code>（加载条与守卫默认开）、<code>WHITE_ROUTES</code>（路由名白名单）、<code>SUPER_ADMIN</code>（默认空）、<code>LAYOUT_CONTENT_REF</code> / <code>LAYOUT_SIDER_REF</code>。</td></tr><tr><td><code>apps/admin/src/app-config/regex-config.ts</code></td><td><code>APP_REGEX</code>，模板 CSS 尺寸规则。</td></tr><tr><td><code>vite.custom.config.ts</code></td><td><code>base</code>、<code>server</code>、<code>buildOptions(mode)</code>、<code>alias</code>、<code>cdn</code>、<code>copyright</code>、Sass 注入和首屏加载配置。</td></tr></tbody></table><h2 id="选择改动入口" tabindex="-1">选择改动入口 <a class="header-anchor" href="#选择改动入口" aria-label="Permalink to &quot;选择改动入口&quot;">​</a></h2><ul><li>修改默认用户偏好（布局、菜单、标签、缓存）时看 <a href="./store/setting.html">Setting Store</a> 与 <code>apps/admin/src/store/modules/setting/constant.ts</code>。已有用户可在应用设置里恢复默认后检查效果。</li><li>修改主题或语言时看<a href="./../guide/appearance.html">主题和国际化</a>。新增语言同时维护翻译资源与 Day.js、Naive UI 对应关系。</li><li>修改访问控制时看<a href="./../guide/routing.html">路由指南</a>。白名单按区分大小写的字符串路由名判断，守卫先处理 token，再按白名单和角色处理导航。</li><li>修改 API 地址、认证头和失败策略时看<a href="./../guide/requests.html">接口与 Mock</a>。应用不会自动把任意 <code>VITE_*</code> 环境变量绑定到 Axios；需在配置中明确读取。</li><li>应用默认部署子路径 <code>/ray-template/</code>。部署子路径改变后重新构建并验证图标、代理和直达链接，见<a href="./../guide/tooling.html">工程与部署</a>。</li></ul><p><code>__APP_CFG__</code> 由 Vite 在构建时注入，用于应用包信息、版权与默认主色。任何注入到客户端的字段都可被浏览器读取。用于页面交互的运行态偏好走 Store，构建参数留在 Vite 配置。</p><p><a href="https://github.com/XiaoDaiGua-Ray/ray-template/tree/2c6bd6b499bc1918ef9e9305d6ed78553c0503c7/apps/admin/src/app-config" target="_blank" rel="noreferrer">应用配置源码</a> · <a href="https://github.com/XiaoDaiGua-Ray/ray-template/blob/2c6bd6b499bc1918ef9e9305d6ed78553c0503c7/vite.custom.config.ts" target="_blank" rel="noreferrer">Vite 自定义配置</a></p>',7)])])}const A=o(a,[["render",r]]);export{f as __pageData,A as default};
